const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || $input.item.json.choices?.[0]?.message?.content || "{}";

let est;
try { est = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { est = m ? JSON.parse(m[0]) : {}; } catch(e2) { est = {}; }
}

const ctx = $("🔧 Preparar Contexto").item.json;

// Helper: convierte string a array (separa por comas o pipes)
const toArray = (v) => {
  if (Array.isArray(v)) return v;
  if (!v) return [];
  return v.split(/[,|]/).map(s => s.trim()).filter(Boolean);
};

// Helper: trunca a max 100 chars tomando solo la primera oración/frase
const truncate = (v, max = 100) => {
  if (!v) return "";
  const str = String(v);
  if (str.length <= max) return str;
  // Corta en el último espacio antes del límite
  return str.substring(0, max).replace(/\s+\S*$/, "").trim();
};

return [{ json: {
  company_id:          Number(ctx.company_id) || 1,
  objetivo:            est.objetivo             || ctx.objetivo  || "",
  audiencia:           est.audiencia            || ctx.audiencia || "",
  tono:                truncate(est.tono || "profesional y directo"),
  frecuencia:          truncate(est.frecuencia  || ""),
  cta_principal:        est.cta_principal         || ctx.web       || "",
  embudo:              truncate(est.embudo      || ""),
  plataformas:         toArray(est.plataformas),
  pilares:             toArray(est.pilares),
  kpis:                toArray(est.kpis),
  resumen_estrategico: est.resumen_estrategico  || "",
  keyword_strategy:    est.keyword_strategy     || {},
  mapa_preguntas_aeo:  est.mapa_preguntas_aeo   || [],
  faqs:                est.faqs                 || [],
  clusters:            est.clusters             || [],
  plan_publicacion:    est.plan_publicacion     || {},
  ideas_plan:          est.ideas_plan           || [],
  empresa_nombre:      ctx.empresa_nombre,
  email:               ctx.email,
  tiempo_horizonte:    ctx.tiempo_horizonte,
  total_ideas:         ctx.total_ideas,
  ideas_generadas:     (est.ideas_plan||[]).length
} }];

